        return result;

    // Create a vector of pairs (distance, index) for all points
    std::vector<std::pair<double, std::size_t>> distances;
    distances.reserve(points.size());

    for (std::size_t i = 0; i < points.size(); ++i)
    {
        double dx = points[i].x - searchPoint.x;
        double dy = points[i].y - searchPoint.y;
        double dz = points[i].z - searchPoint.z;
        double distance = dx * dx + dy * dy + dz * dz; // Squared distance for efficiency
        distances.emplace_back(distance, i);
    }

    // Partial sort to get the k smallest distances
    std::partial_sort(
        distances.begin(),
        distances.begin() + std::min(k, distances.size()),
        distances.end(),
        [](const auto& a, const auto& b) {
            return a.first < b.first;
        }
    );

    // Extract the indices of the k nearest neighbors
    result.reserve(k);
    for (std::size_t i = 0; i < std::min(k, distances.size()); ++i)
    {
        result.push_back(distances[i].second);
    }

    return result;
